package com.earthtrip.platform.adapter.in.web.api.v1.geocoding.reverse;
import com.earthtrip.platform.application.port.in.ExternalTravelUseCase;import java.math.BigDecimal;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/v1/geocoding/reverse")class ReverseGeocodingController{private final ExternalTravelUseCase u;ReverseGeocodingController(ExternalTravelUseCase u){this.u=u;}@GetMapping ExternalTravelUseCase.GeoResult get(@RequestParam BigDecimal latitude,@RequestParam BigDecimal longitude,@RequestParam(required=false)String language){return u.reverse(latitude,longitude,language);}}
